import{_ as a,o as e,c as r,ae as i}from"./chunks/framework.Dh1jimFm.js";const m=JSON.parse('{"title":"Translation Memory Basics","description":"","frontmatter":{},"headers":[],"relativePath":"translation-memory/basics.md","filePath":"translation-memory/basics.md"}'),s={name:"translation-memory/basics.md"};function o(l,t,n,h,d,c){return e(),r("div",null,t[0]||(t[0]=[i('<h1 id="translation-memory-basics" tabindex="-1">Translation Memory Basics <a class="header-anchor" href="#translation-memory-basics" aria-label="Permalink to &quot;Translation Memory Basics&quot;">​</a></h1><p>Translation Memory (TM) helps you reuse previous translations.</p><h2 id="what-is-translation-memory" tabindex="-1">What is Translation Memory? <a class="header-anchor" href="#what-is-translation-memory" aria-label="Permalink to &quot;What is Translation Memory?&quot;">​</a></h2><p>A Translation Memory stores pairs of source and target text:</p><table tabindex="0"><thead><tr><th>Source</th><th>Target</th><th>Match %</th></tr></thead><tbody><tr><td>&quot;Save the file&quot;</td><td>&quot;Sla het bestand op&quot;</td><td>100%</td></tr><tr><td>&quot;Save the document&quot;</td><td>&quot;Sla het document op&quot;</td><td>85%</td></tr></tbody></table><p>When you translate new text, the TM finds similar segments.</p><h2 id="how-tm-works" tabindex="-1">How TM Works <a class="header-anchor" href="#how-tm-works" aria-label="Permalink to &quot;How TM Works&quot;">​</a></h2><ol><li><strong>You translate</strong> a segment</li><li><strong>TM stores</strong> the source + target pair</li><li><strong>Later</strong>, when similar text appears: <ul><li>TM finds matches</li><li>Shows them in the Translation Results panel</li><li>You can insert or adapt them</li></ul></li></ol><h2 id="match-types" tabindex="-1">Match Types <a class="header-anchor" href="#match-types" aria-label="Permalink to &quot;Match Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Match %</th><th>Description</th></tr></thead><tbody><tr><td><strong>Exact</strong></td><td>100%</td><td>Identical source text</td></tr><tr><td><strong>High Fuzzy</strong></td><td>90-99%</td><td>Minor differences (numbers, capitalization)</td></tr><tr><td><strong>Medium Fuzzy</strong></td><td>75-89%</td><td>Some words different</td></tr><tr><td><strong>Low Fuzzy</strong></td><td>50-74%</td><td>Significant differences</td></tr></tbody></table><h2 id="benefits" tabindex="-1">Benefits <a class="header-anchor" href="#benefits" aria-label="Permalink to &quot;Benefits&quot;">​</a></h2><h3 id="save-time" tabindex="-1">Save Time <a class="header-anchor" href="#save-time" aria-label="Permalink to &quot;Save Time&quot;">​</a></h3><p>Don&#39;t translate the same sentence twice. TM automatically suggests previous translations.</p><h3 id="consistency" tabindex="-1">Consistency <a class="header-anchor" href="#consistency" aria-label="Permalink to &quot;Consistency&quot;">​</a></h3><p>Same source = same translation. Important for technical documentation, UI strings, and legal text.</p><h3 id="cost-savings" tabindex="-1">Cost Savings <a class="header-anchor" href="#cost-savings" aria-label="Permalink to &quot;Cost Savings&quot;">​</a></h3><p>Clients often pay less for TM matches:</p><ul><li>100% match: Lowest rate</li><li>Fuzzy match: Reduced rate</li><li>New text: Full rate</li></ul><h2 id="tm-in-supervertaler" tabindex="-1">TM in Supervertaler <a class="header-anchor" href="#tm-in-supervertaler" aria-label="Permalink to &quot;TM in Supervertaler&quot;">​</a></h2><h3 id="translation-results-panel" tabindex="-1">Translation Results Panel <a class="header-anchor" href="#translation-results-panel" aria-label="Permalink to &quot;Translation Results Panel&quot;">​</a></h3><p>When you select a segment:</p><ol><li>TM searches for matches</li><li>Results appear in the panel on the right</li><li>Shows match percentage, source, and target</li><li>Double-click to insert</li></ol><h3 id="using-matches" tabindex="-1">Using Matches <a class="header-anchor" href="#using-matches" aria-label="Permalink to &quot;Using Matches&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>How</th></tr></thead><tbody><tr><td>Insert match</td><td>Double-click or press <code>Ctrl+1-9</code> for first 9 matches</td></tr><tr><td>Copy match</td><td>Right-click → Copy</td></tr><tr><td>View in context</td><td>Right-click → View in TM</td></tr></tbody></table><h3 id="building-tm" tabindex="-1">Building TM <a class="header-anchor" href="#building-tm" aria-label="Permalink to &quot;Building TM&quot;">​</a></h3><p>Your TM grows as you translate:</p><ol><li>Translate a segment</li><li>Confirm with <code>Ctrl+Enter</code></li><li>The pair is saved to active TM</li></ol><h2 id="multiple-tms" tabindex="-1">Multiple TMs <a class="header-anchor" href="#multiple-tms" aria-label="Permalink to &quot;Multiple TMs&quot;">​</a></h2><p>You can have multiple TMs:</p><ul><li><strong>Project TM</strong>: For the current project</li><li><strong>Client TMs</strong>: One per client</li><li><strong>Master TM</strong>: All your translations</li></ul><h3 id="tm-priority" tabindex="-1">TM Priority <a class="header-anchor" href="#tm-priority" aria-label="Permalink to &quot;TM Priority&quot;">​</a></h3><p>When multiple TMs match:</p><ul><li>Higher priority TMs shown first</li><li>Can reorder in Project resources</li></ul><hr><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./managing-tms.html">Creating &amp; Managing TMs</a></li><li><a href="./importing-tmx.html">Importing TMX Files</a></li><li><a href="./fuzzy-matching.html">Fuzzy Matching</a></li><li><a href="./supermemory.html">Supermemory (Semantic Search)</a></li></ul>',36)]))}const p=a(s,[["render",o]]);export{m as __pageData,p as default};
